import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"WAF — enumerated source for the Well-Architected service guides","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-service-guides-checklist.md","filePath":"frameworks/waf-service-guides-checklist.md"}'),i={name:"frameworks/waf-service-guides-checklist.md"};function o(n,t,c,s,l,u){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="waf-—-enumerated-source-for-the-well-architected-service-guides" tabindex="-1">WAF — enumerated source for the Well-Architected service guides <a class="header-anchor" href="#waf-—-enumerated-source-for-the-well-architected-service-guides" aria-label="Permalink to &quot;WAF — enumerated source for the Well-Architected service guides&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.serviceguides.yaml</code> scores an estate against the &quot;Configuration recommendations&quot; that Microsoft publishes in each Azure Well-Architected Framework <a href="https://learn.microsoft.com/azure/well-architected/service-guides/" target="_blank" rel="noreferrer">service guide</a>. This page enumerates the recommendations Scout turns into a rule. <code>src/assess/rules/waf.serviceguides.yaml</code> is written against this page only, and every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/azure/well-architected/service-guides/" target="_blank" rel="noreferrer">Well-Architected Framework perspective on Azure services</a> (20 service guides read; Microsoft publishes no assessment questions for them)</td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework service guides on Microsoft Learn, current; guide pages last updated between 2025-02 and 2026-11</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Each guide page below was fetched in full on 2026-11-25 (the Azure Kubernetes Service and App Service guides with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool, the rest from the Microsoft Learn markdown endpoint, which serves the same page), and its Configuration recommendations tables, workload design checklists and Azure policies sections were read. Every field an automated item reads was checked against the collect contract in <code>src/collect/Invoke-Collect.ps1</code> and the KQL that projects it.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not a list Microsoft numbers.</strong> The guides carry unnumbered recommendation tables, and Microsoft publishes no assessment for them. The items below are <strong>Scout&#39;s</strong> reading of those tables, and the <code>WAF-SVC-*</code> IDs are Scout&#39;s. Where one recommendation is split across several settings, each setting is its own item; where a recommendation is a process (rehearse a failover, review a policy), it is a manual item.</p><p>Two of the guides are not in the index page&#39;s list but are published and are covered: Azure Container Apps and Azure Virtual WAN. The Virtual Machines guide covers virtual machines and scale sets together, so scale-set items carry their own <code>WAF-SVC-VMSS</code> prefix. The guides for Blob Storage, Cosmos DB, MySQL, PostgreSQL, SQL, Managed Redis, Databricks, Event Hubs, Machine Learning, Azure Local, Log Analytics, Service Fabric and HorizonDB are not enumerated here; several are already scored by their own rule files.</p><h2 id="reading-the-tables" tabindex="-1">Reading the tables <a class="header-anchor" href="#reading-the-tables" aria-label="Permalink to &quot;Reading the tables&quot;">​</a></h2><ul><li><strong>Scout ✅</strong> means a collected field answers the item, and the rule lists the resources that break it. <strong>Scout ❌ Manual</strong> means no collected field answers it; where there is some related evidence it is attached to the question.</li><li>Automated items are <strong>gated</strong>: they run only when the guide&#39;s resource type exists, so an estate without it reports the item Not assessed. Manual items are gated the same way.</li><li>Zone items are limited to the regions in Scout&#39;s zone-eligible list. A resource in a region without availability zones is not failed for lacking them.</li><li>Recommendations that conflict across pillars (a Premium tier for reliability against Basic for cost, scale to zero against replica counts) are scored on the stricter reliability or security reading at low or medium severity, and the remediation says when a lower setting is legitimate.</li></ul><p>Guides enumerated:</p><ul><li><strong>Azure Kubernetes Service</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-kubernetes-service" target="_blank" rel="noreferrer">azure-kubernetes-service</a></li><li><strong>Azure App Service (Web Apps)</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/app-service-web-apps" target="_blank" rel="noreferrer">app-service-web-apps</a></li><li><strong>Azure Functions</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-functions" target="_blank" rel="noreferrer">azure-functions</a></li><li><strong>Azure Container Apps</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-container-apps" target="_blank" rel="noreferrer">azure-container-apps</a></li><li><strong>Azure API Management</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-api-management" target="_blank" rel="noreferrer">azure-api-management</a></li><li><strong>Azure Service Bus</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-service-bus" target="_blank" rel="noreferrer">azure-service-bus</a></li><li><strong>Azure Event Grid</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-event-grid" target="_blank" rel="noreferrer">azure-event-grid</a></li><li><strong>Azure Firewall</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-firewall" target="_blank" rel="noreferrer">azure-firewall</a></li><li><strong>Azure Application Gateway</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-application-gateway" target="_blank" rel="noreferrer">azure-application-gateway</a></li><li><strong>Azure Load Balancer</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-load-balancer" target="_blank" rel="noreferrer">azure-load-balancer</a></li><li><strong>Azure Virtual Network</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/virtual-network" target="_blank" rel="noreferrer">virtual-network</a></li><li><strong>Azure Virtual Machines</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/virtual-machines" target="_blank" rel="noreferrer">virtual-machines</a></li><li><strong>Azure Virtual Machine Scale Sets</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/virtual-machines" target="_blank" rel="noreferrer">virtual-machines</a></li><li><strong>Azure Disk Storage</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-disk-storage" target="_blank" rel="noreferrer">azure-disk-storage</a></li><li><strong>Azure Monitor Application Insights</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/application-insights" target="_blank" rel="noreferrer">application-insights</a></li><li><strong>Azure Front Door</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-front-door" target="_blank" rel="noreferrer">azure-front-door</a></li><li><strong>Azure Traffic Manager</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-traffic-manager" target="_blank" rel="noreferrer">azure-traffic-manager</a></li><li><strong>Azure Virtual WAN</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-virtual-wan" target="_blank" rel="noreferrer">azure-virtual-wan</a></li><li><strong>Azure ExpressRoute</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-expressroute" target="_blank" rel="noreferrer">azure-expressroute</a></li><li><strong>Azure Files</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-files" target="_blank" rel="noreferrer">azure-files</a></li><li><strong>Azure NetApp Files</strong> — <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-netapp-files" target="_blank" rel="noreferrer">azure-netapp-files</a></li></ul><h2 id="the-enumeration-—-214-items-across-21-service-sections" tabindex="-1">The enumeration — 214 items across 21 service sections <a class="header-anchor" href="#the-enumeration-—-214-items-across-21-service-sections" aria-label="Permalink to &quot;The enumeration — 214 items across 21 service sections&quot;">​</a></h2><h3 id="azure-kubernetes-service-waf-svc-aks-—-14-items" tabindex="-1">Azure Kubernetes Service (WAF-SVC-AKS) — 14 items <a class="header-anchor" href="#azure-kubernetes-service-waf-svc-aks-—-14-items" aria-label="Permalink to &quot;Azure Kubernetes Service (WAF-SVC-AKS) — 14 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-kubernetes-service" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-kubernetes-service</a>. 12 automated, 2 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-AKS-01</td><td>Clusters use the Standard or Premium tier, which carries the uptime SLA</td><td>Reliability</td><td>✅ <code>tier</code></td></tr><tr><td>WAF-SVC-AKS-02</td><td>Every node pool is spread across availability zones</td><td>Reliability</td><td>✅ <code>allPoolsZoned</code>, in zone regions</td></tr><tr><td>WAF-SVC-AKS-03</td><td>Clusters authenticate users through Microsoft Entra ID</td><td>Security</td><td>✅ <code>aadIntegrated</code></td></tr><tr><td>WAF-SVC-AKS-04</td><td>Local accounts are disabled so every access goes through Microsoft Entra ID</td><td>Security</td><td>✅ <code>disableLocalAccounts</code></td></tr><tr><td>WAF-SVC-AKS-05</td><td>Kubernetes authorization uses Azure RBAC</td><td>Security</td><td>✅ <code>azureRbac</code></td></tr><tr><td>WAF-SVC-AKS-06</td><td>Public clusters limit the API server to authorized IP ranges</td><td>Security</td><td>✅ <code>privateCluster</code>, <code>authorizedIpRangeCount</code></td></tr><tr><td>WAF-SVC-AKS-07</td><td>Workloads use Microsoft Entra Workload ID</td><td>Security</td><td>✅ <code>workloadIdentity</code></td></tr><tr><td>WAF-SVC-AKS-08</td><td>Microsoft Defender for Containers is enabled</td><td>Security</td><td>✅ <code>defenderEnabled</code></td></tr><tr><td>WAF-SVC-AKS-09</td><td>A network policy secures traffic between pods</td><td>Security</td><td>✅ <code>networkPolicyEnabled</code></td></tr><tr><td>WAF-SVC-AKS-10</td><td>Automatic cluster upgrades are enabled</td><td>Operational excellence</td><td>✅ <code>upgradeChannel</code></td></tr><tr><td>WAF-SVC-AKS-11</td><td>The cluster autoscaler scales every node pool</td><td>Cost optimization</td><td>✅ <code>allPoolsAutoscale</code></td></tr><tr><td>WAF-SVC-AKS-12</td><td>Clusters that need strong API segmentation are private, and egress passes through a firewall, NAT gateway or proxy</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-AKS-13</td><td>Azure Policy and deployment safeguards enforce pod and cluster standards</td><td>Security</td><td>✅ <code>azurePolicyAddon</code>; the deployment safeguards level and the policy assignments are not read</td></tr><tr><td>WAF-SVC-AKS-14</td><td>Cluster state and application data are backed up, and maintenance is scheduled</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-app-service-web-apps-waf-svc-app-—-17-items" tabindex="-1">Azure App Service (Web Apps) (WAF-SVC-APP) — 17 items <a class="header-anchor" href="#azure-app-service-web-apps-waf-svc-app-—-17-items" aria-label="Permalink to &quot;Azure App Service (Web Apps) (WAF-SVC-APP) — 17 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/app-service-web-apps" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/app-service-web-apps</a>. 14 automated, 3 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-APP-01</td><td>App Service plans use the Premium v3 tier or above</td><td>Reliability</td><td>✅ <code>tier</code></td></tr><tr><td>WAF-SVC-APP-02</td><td>Plans on a zone-capable tier are zone redundant</td><td>Reliability</td><td>✅ <code>zoneRedundant</code>, in zone regions</td></tr><tr><td>WAF-SVC-APP-03</td><td>Plans run more than one instance</td><td>Reliability</td><td>✅ <code>instanceCount</code></td></tr><tr><td>WAF-SVC-APP-04</td><td>Plans on a tier that supports it have an enabled autoscale setting</td><td>Performance efficiency</td><td>✅ <code>appServicePlans</code> to enabled <code>autoscaleSettings</code></td></tr><tr><td>WAF-SVC-APP-05</td><td>Web apps have a managed identity</td><td>Security</td><td>✅ <code>identityType</code></td></tr><tr><td>WAF-SVC-APP-06</td><td>Web apps accept HTTPS only</td><td>Security</td><td>✅ <code>httpsOnly</code></td></tr><tr><td>WAF-SVC-APP-07</td><td>Web apps require TLS 1.2 or higher</td><td>Security</td><td>✅ <code>minTls</code></td></tr><tr><td>WAF-SVC-APP-08</td><td>Web apps block public network access</td><td>Security</td><td>✅ <code>publicNetworkAccess</code></td></tr><tr><td>WAF-SVC-APP-09</td><td>Web apps are integrated with a virtual network</td><td>Security</td><td>✅ <code>vnetIntegrated</code></td></tr><tr><td>WAF-SVC-APP-10</td><td>Web apps use a custom domain</td><td>Security</td><td>✅ <code>customDomainBound</code></td></tr><tr><td>WAF-SVC-APP-11</td><td>Microsoft Defender for App Service is enabled</td><td>Security</td><td>✅ Defender plan <code>AppServices</code></td></tr><tr><td>WAF-SVC-APP-12</td><td>Web apps send diagnostic logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.web/sites</code></td></tr><tr><td>WAF-SVC-APP-13</td><td>Health check, auto-heal and Always On are configured</td><td>Reliability</td><td>✅ <code>webAppConfig</code> <code>healthCheckPathSet</code> and <code>alwaysOn</code>, web apps only (a function app has no Always On); auto-heal is not collected</td></tr><tr><td>WAF-SVC-APP-14</td><td>Basic authentication, FTP and remote debugging are disabled, and secrets use Key Vault references</td><td>Security</td><td>✅ <code>webAppBasicAuth</code> <code>ftpBasicAuthAllowed</code> and <code>scmBasicAuthAllowed</code>, <code>webAppConfig</code> <code>ftpsState</code> (AllAllowed is a finding) and <code>remoteDebuggingEnabled</code>; covers web and function apps, a policy that was not returned is not scored; Key Vault references are not collected</td></tr><tr><td>WAF-SVC-APP-15</td><td>Built-in authentication or Microsoft Entra ID authentication protects the app, with restrictive CORS</td><td>Security</td><td>❌ Manual — with evidence: each web app&#39;s built-in authentication settings (<code>domains.web.webAppAuth</code>: switched on, required, action for unauthenticated clients, identity providers on, Entra ID on); an app can authenticate in its own code, so authentication being off is not scored; CORS is not read</td></tr><tr><td>WAF-SVC-APP-16</td><td>Releases go through deployment slots and a pipeline</td><td>Operational excellence</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-APP-17</td><td>Lower environments use Free or Basic plans, and steady workloads use reservations</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-functions-waf-svc-func-—-7-items" tabindex="-1">Azure Functions (WAF-SVC-FUNC) — 7 items <a class="header-anchor" href="#azure-functions-waf-svc-func-—-7-items" aria-label="Permalink to &quot;Azure Functions (WAF-SVC-FUNC) — 7 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-functions" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-functions</a>. 4 automated, 3 manual.</p><p>The Functions guide builds on the App Service guide; function apps are the web apps whose <code>kind</code> contains functionapp.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-FUNC-01</td><td>Function apps have a managed identity</td><td>Security</td><td>✅ <code>identityType</code></td></tr><tr><td>WAF-SVC-FUNC-02</td><td>Function apps accept HTTPS only</td><td>Security</td><td>✅ <code>httpsOnly</code></td></tr><tr><td>WAF-SVC-FUNC-03</td><td>Function apps block public network access</td><td>Security</td><td>✅ <code>publicNetworkAccess</code></td></tr><tr><td>WAF-SVC-FUNC-04</td><td>Function apps are integrated with a virtual network</td><td>Security</td><td>✅ <code>vnetIntegrated</code></td></tr><tr><td>WAF-SVC-FUNC-05</td><td>Secrets come from Key Vault and the app requires Microsoft Entra ID authentication</td><td>Security</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-FUNC-06</td><td>Retries, Durable Functions and availability zones are used where the workload needs them</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-FUNC-07</td><td>Function apps send telemetry to Application Insights and deploy through CI/CD with slots</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-container-apps-waf-svc-aca-—-11-items" tabindex="-1">Azure Container Apps (WAF-SVC-ACA) — 11 items <a class="header-anchor" href="#azure-container-apps-waf-svc-aca-—-11-items" aria-label="Permalink to &quot;Azure Container Apps (WAF-SVC-ACA) — 11 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-container-apps" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-container-apps</a>. 8 automated, 3 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-ACA-01</td><td>Environments are zone redundant</td><td>Reliability</td><td>✅ <code>zoneRedundant</code>, in zone regions</td></tr><tr><td>WAF-SVC-ACA-02</td><td>Apps with ingress keep at least three replicas</td><td>Reliability</td><td>✅ <code>externalIngress</code>, <code>minReplicas</code></td></tr><tr><td>WAF-SVC-ACA-03</td><td>Apps accept HTTPS only</td><td>Security</td><td>✅ <code>allowInsecure</code></td></tr><tr><td>WAF-SVC-ACA-04</td><td>Apps have a managed identity</td><td>Security</td><td>✅ <code>identityType</code></td></tr><tr><td>WAF-SVC-ACA-05</td><td>Environments are injected into a virtual network</td><td>Security</td><td>✅ <code>vnetIntegrated</code></td></tr><tr><td>WAF-SVC-ACA-06</td><td>Environments block public network access</td><td>Security</td><td>✅ <code>internal</code>, <code>publicNetworkAccess</code></td></tr><tr><td>WAF-SVC-ACA-07</td><td>Apps that must not be public use internal ingress, and a WAF fronts the ones that are</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ACA-08</td><td>Secrets use Key Vault, registry pulls use Microsoft Entra ID, and egress is controlled</td><td>Security</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-ACA-09</td><td>Health probes, resource limits and resiliency policies are configured</td><td>Reliability</td><td>✅ <code>containersWithoutAllProbes</code>; resource limits (always allocated by the platform) and resiliency policies are not scored</td></tr><tr><td>WAF-SVC-ACA-10</td><td>Scale rules match the workload</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-ACA-11</td><td>Logs and traces go to Log Analytics, Application Insights or an OpenTelemetry agent</td><td>Operational excellence</td><td>✅ <code>logsExported</code> on the environment; tracing is not read</td></tr></tbody></table><h3 id="azure-api-management-waf-svc-apim-—-12-items" tabindex="-1">Azure API Management (WAF-SVC-APIM) — 12 items <a class="header-anchor" href="#azure-api-management-waf-svc-apim-—-12-items" aria-label="Permalink to &quot;Azure API Management (WAF-SVC-APIM) — 12 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-api-management" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-api-management</a>. 10 automated, 2 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-APIM-01</td><td>Premium instances are zone redundant</td><td>Reliability</td><td>✅ <code>zoneCount</code></td></tr><tr><td>WAF-SVC-APIM-02</td><td>Premium instances run at least two units</td><td>Reliability</td><td>✅ <code>capacity</code></td></tr><tr><td>WAF-SVC-APIM-03</td><td>Premium instances use a multiregion topology</td><td>Reliability</td><td>✅ <code>additionalRegionCount</code></td></tr><tr><td>WAF-SVC-APIM-04</td><td>Instances on a tier that supports it have an enabled autoscale setting</td><td>Reliability</td><td>✅ <code>apiManagement</code> to enabled <code>autoscaleSettings</code></td></tr><tr><td>WAF-SVC-APIM-05</td><td>The gateway is not open to the internet without network controls</td><td>Security</td><td>✅ <code>publicNetworkAccess</code>, <code>virtualNetworkType</code></td></tr><tr><td>WAF-SVC-APIM-06</td><td>Instances have a managed identity</td><td>Security</td><td>✅ <code>identityType</code></td></tr><tr><td>WAF-SVC-APIM-07</td><td>Microsoft Defender for APIs is enabled</td><td>Security</td><td>✅ Defender plan <code>Api</code></td></tr><tr><td>WAF-SVC-APIM-08</td><td>Instances send resource logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.apimanagement/service</code></td></tr><tr><td>WAF-SVC-APIM-09</td><td>The narrowest TLS versions, protocols and ciphers are set, and the developer portal and direct management API are off</td><td>Security</td><td>✅ <code>legacyProtocolEnabled</code>, <code>legacyCipherEnabled</code>; the developer portal and the direct management API are not read</td></tr><tr><td>WAF-SVC-APIM-10</td><td>APIs authenticate with OAuth 2.0, secrets use Key Vault named values, and a WAF fronts internet-exposed gateways</td><td>Security</td><td>✅ <code>domains.integration.apimNamedValues</code> — a service holding a secret named value inline instead of in Key Vault fails; the global policy&#39;s token validation and the count of APIs with token authentication (<code>apimGlobalPolicy</code>, <code>apimApis</code>) are evidence, because a <code>validate-jwt</code> policy can sit on one API or operation, which is not read</td></tr><tr><td>WAF-SVC-APIM-11</td><td>Backup, restore and a disaster recovery playbook exist, and unrelated APIs are isolated</td><td>Reliability</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-APIM-12</td><td>The tier is the least expensive that meets the workload, and lower environments use non-production tiers</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-service-bus-waf-svc-sb-—-13-items" tabindex="-1">Azure Service Bus (WAF-SVC-SB) — 13 items <a class="header-anchor" href="#azure-service-bus-waf-svc-sb-—-13-items" aria-label="Permalink to &quot;Azure Service Bus (WAF-SVC-SB) — 13 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-service-bus" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-service-bus</a>. 10 automated, 3 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-SB-01</td><td>Namespaces use the Premium tier</td><td>Reliability</td><td>✅ <code>tier</code></td></tr><tr><td>WAF-SVC-SB-02</td><td>Namespaces are zone redundant in regions that have zones</td><td>Reliability</td><td>✅ <code>zoneRedundant</code>, in zone regions</td></tr><tr><td>WAF-SVC-SB-03</td><td>Premium namespaces replicate to a second region</td><td>Reliability</td><td>✅ <code>geoReplicaCount</code></td></tr><tr><td>WAF-SVC-SB-04</td><td>Shared access key authentication is disabled</td><td>Security</td><td>✅ <code>disableLocalAuth</code></td></tr><tr><td>WAF-SVC-SB-05</td><td>Namespaces require TLS 1.2</td><td>Security</td><td>✅ <code>minimumTlsVersion</code></td></tr><tr><td>WAF-SVC-SB-06</td><td>Premium namespaces block public network access</td><td>Security</td><td>✅ <code>publicAccess</code></td></tr><tr><td>WAF-SVC-SB-07</td><td>Premium namespaces have a private endpoint</td><td>Security</td><td>✅ <code>serviceBusNamespaces</code> to <code>privateEndpoints</code></td></tr><tr><td>WAF-SVC-SB-08</td><td>Premium namespaces encrypt with a customer-managed key</td><td>Security</td><td>✅ <code>cmkKeySource</code></td></tr><tr><td>WAF-SVC-SB-09</td><td>Namespaces send security and operational logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.servicebus/namespaces</code></td></tr><tr><td>WAF-SVC-SB-10</td><td>Geo-replication or geo-disaster recovery has a rehearsed regional recovery runbook</td><td>Reliability</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-SB-11</td><td>Consumers use PeekLock, duplicate detection and dead-lettering, and alerts watch queue depth and throttling</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-SB-12</td><td>Access uses least-privilege Azure RBAC, IP firewall rules, and Key Vault for any remaining keys</td><td>Security</td><td>✅ <code>domains.integration.serviceBusNetworkRuleSets</code> — a Premium namespace (the only tier with IP firewall rules) open to every network fails; the authorization rules (<code>serviceBusAuthorization</code>) are evidence; Azure RBAC role assignments are not read</td></tr><tr><td>WAF-SVC-SB-13</td><td>Premium autoscale, batching, prefetch and partitioning are tuned by load test</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr></tbody></table><h3 id="azure-event-grid-waf-svc-eg-—-10-items" tabindex="-1">Azure Event Grid (WAF-SVC-EG) — 10 items <a class="header-anchor" href="#azure-event-grid-waf-svc-eg-—-10-items" aria-label="Permalink to &quot;Azure Event Grid (WAF-SVC-EG) — 10 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-event-grid" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-event-grid</a>. 6 automated, 4 manual.</p><p>The guide index links the Event Grid guide as event-grid/reliability; the guide itself is service-guides/azure-event-grid.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-EG-01</td><td>Topics and domains disable key-based authentication</td><td>Security</td><td>✅ <code>disableLocalAuth</code></td></tr><tr><td>WAF-SVC-EG-02</td><td>Public access is disabled or limited by an IP allow list</td><td>Security</td><td>✅ <code>publicNetworkAccess</code>, <code>inboundIpRuleCount</code></td></tr><tr><td>WAF-SVC-EG-03</td><td>Resources require TLS 1.2 or higher</td><td>Security</td><td>✅ <code>minimumTlsVersion</code></td></tr><tr><td>WAF-SVC-EG-04</td><td>Resources have a managed identity for delivery</td><td>Security</td><td>✅ <code>identityType</code></td></tr><tr><td>WAF-SVC-EG-05</td><td>Resources have a private endpoint</td><td>Security</td><td>✅ <code>eventGrid</code> to <code>privateEndpoints</code></td></tr><tr><td>WAF-SVC-EG-06</td><td>Resources send diagnostic logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.eventgrid/*</code></td></tr><tr><td>WAF-SVC-EG-07</td><td>Retries, dead-lettering and cross-geo failover are configured</td><td>Reliability</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-EG-08</td><td>Delivery success, dead-letter volume and latency are alerted on</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-EG-09</td><td>Management is least-privilege RBAC with Conditional Access, and secrets are in Key Vault</td><td>Security</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-EG-10</td><td>The Event Grid tier and event filters match usage</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-firewall-waf-svc-fw-—-11-items" tabindex="-1">Azure Firewall (WAF-SVC-FW) — 11 items <a class="header-anchor" href="#azure-firewall-waf-svc-fw-—-11-items" aria-label="Permalink to &quot;Azure Firewall (WAF-SVC-FW) — 11 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-firewall" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-firewall</a>. 7 automated, 4 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-FW-01</td><td>Firewalls are deployed across multiple availability zones</td><td>Reliability</td><td>✅ <code>zoneCount</code></td></tr><tr><td>WAF-SVC-FW-02</td><td>Firewalls use a firewall policy, not classic rules</td><td>Security</td><td>✅ <code>hasPolicy</code></td></tr><tr><td>WAF-SVC-FW-03</td><td>Firewall policies run threat intelligence in Alert and deny mode</td><td>Security</td><td>✅ <code>firewallPolicies.threatIntelMode</code></td></tr><tr><td>WAF-SVC-FW-04</td><td>Firewalls without a policy run threat intelligence in Alert and deny mode</td><td>Security</td><td>✅ <code>threatIntelMode</code></td></tr><tr><td>WAF-SVC-FW-05</td><td>Firewalls protecting sensitive workloads use the Premium tier</td><td>Security</td><td>✅ <code>tier</code></td></tr><tr><td>WAF-SVC-FW-06</td><td>IDPS, TLS inspection and DNS proxy are enabled on the policy</td><td>Security</td><td>✅ <code>idpsTlsDnsEnabled</code> on policies with no base policy</td></tr><tr><td>WAF-SVC-FW-07</td><td>Traffic is forced through the firewall by user-defined routes or routing intent</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-FW-08</td><td>Resource Health, throughput, SNAT and health-state alerts exist</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-FW-09</td><td>Customer-controlled maintenance is configured</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-FW-10</td><td>Policy analytics, IP groups, enough public IPs for SNAT and prescaling are in use</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-FW-11</td><td>Firewalls send logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.network/azurefirewalls</code></td></tr></tbody></table><h3 id="azure-application-gateway-waf-svc-agw-—-13-items" tabindex="-1">Azure Application Gateway (WAF-SVC-AGW) — 13 items <a class="header-anchor" href="#azure-application-gateway-waf-svc-agw-—-13-items" aria-label="Permalink to &quot;Azure Application Gateway (WAF-SVC-AGW) — 13 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-application-gateway" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-application-gateway</a>. 9 automated, 4 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-AGW-01</td><td>Gateways use the v2 SKU</td><td>Reliability</td><td>✅ <code>tier</code></td></tr><tr><td>WAF-SVC-AGW-02</td><td>v2 gateways are zone aware</td><td>Reliability</td><td>✅ <code>zoneCount</code>, in zone regions</td></tr><tr><td>WAF-SVC-AGW-03</td><td>Gateways define custom health probes</td><td>Reliability</td><td>✅ <code>probeCount</code></td></tr><tr><td>WAF-SVC-AGW-04</td><td>Web application firewall is enabled</td><td>Security</td><td>✅ <code>wafEnabled</code></td></tr><tr><td>WAF-SVC-AGW-05</td><td>WAF policies on Application Gateway run in Prevention mode</td><td>Security</td><td>✅ <code>wafPolicies.mode</code></td></tr><tr><td>WAF-SVC-AGW-06</td><td>Gateways set a current TLS policy</td><td>Security</td><td>✅ <code>sslPolicyType</code>, <code>sslPolicyName</code>, <code>sslMinProtocol</code></td></tr><tr><td>WAF-SVC-AGW-07</td><td>v2 gateways autoscale</td><td>Performance efficiency</td><td>✅ <code>autoscaleMax</code></td></tr><tr><td>WAF-SVC-AGW-08</td><td>Autoscale maximum is set to the maximum possible (125)</td><td>Performance efficiency</td><td>✅ <code>autoscaleMax</code></td></tr><tr><td>WAF-SVC-AGW-09</td><td>Gateways and WAF send diagnostic logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.network/applicationgateways</code></td></tr><tr><td>WAF-SVC-AGW-10</td><td>Certificates are in Key Vault, end-to-end TLS is used, and the WAF is tuned with rate limiting</td><td>Security</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-AGW-11</td><td>No user-defined route sits on the gateway subnet, and idle timeout fits the application</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-AGW-12</td><td>Alerts cover capacity units, unhealthy hosts and 4xx/5xx responses</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-AGW-13</td><td>Minimum instance count and a /24 subnet are sized from observed load</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr></tbody></table><h3 id="azure-load-balancer-waf-svc-lb-—-9-items" tabindex="-1">Azure Load Balancer (WAF-SVC-LB) — 9 items <a class="header-anchor" href="#azure-load-balancer-waf-svc-lb-—-9-items" aria-label="Permalink to &quot;Azure Load Balancer (WAF-SVC-LB) — 9 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-load-balancer" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-load-balancer</a>. 5 automated, 4 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-LB-01</td><td>Load balancers use the Standard SKU</td><td>Reliability</td><td>✅ <code>sku</code></td></tr><tr><td>WAF-SVC-LB-02</td><td>Load balancers have at least one load-balancing rule</td><td>Reliability</td><td>✅ <code>ruleCount</code></td></tr><tr><td>WAF-SVC-LB-03</td><td>Load balancers define health probes</td><td>Reliability</td><td>✅ <code>probeCount</code></td></tr><tr><td>WAF-SVC-LB-04</td><td>Internal load balancer frontends are zone redundant</td><td>Reliability</td><td>✅ <code>minFrontendZoneCount</code></td></tr><tr><td>WAF-SVC-LB-05</td><td>Public load balancers are protected by DDoS Protection and back ends are not reachable directly from the internet</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-LB-06</td><td>Load balancers send resource logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.network/loadbalancers</code></td></tr><tr><td>WAF-SVC-LB-07</td><td>Multidimensional metric alerts, Azure Monitor Insights and Admin state are used</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-LB-08</td><td>The global tier, session persistence and probe-down behavior fit the workload</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-LB-09</td><td>Rules are consolidated and unused load balancers are removed</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-virtual-network-waf-svc-vnet-—-13-items" tabindex="-1">Azure Virtual Network (WAF-SVC-VNET) — 13 items <a class="header-anchor" href="#azure-virtual-network-waf-svc-vnet-—-13-items" aria-label="Permalink to &quot;Azure Virtual Network (WAF-SVC-VNET) — 13 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/virtual-network" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/virtual-network</a>. 10 automated, 3 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-VNET-01</td><td>Public IP addresses use the Standard SKU</td><td>Reliability</td><td>✅ <code>skuName</code></td></tr><tr><td>WAF-SVC-VNET-02</td><td>Standard public IP addresses are zone redundant in regions that have zones</td><td>Reliability</td><td>✅ <code>zoneCount</code></td></tr><tr><td>WAF-SVC-VNET-03</td><td>No subnet is close to running out of addresses</td><td>Reliability</td><td>✅ <code>ipUtilizationPct</code></td></tr><tr><td>WAF-SVC-VNET-04</td><td>Virtual network encryption is enabled</td><td>Security</td><td>✅ <code>encryptionEnabled</code></td></tr><tr><td>WAF-SVC-VNET-05</td><td>Azure DDoS Protection covers virtual networks</td><td>Security</td><td>✅ <code>ddosEnabled</code></td></tr><tr><td>WAF-SVC-VNET-06</td><td>No network security group rule allows inbound traffic from any source</td><td>Security</td><td>✅ <code>nsgPublicInbound</code></td></tr><tr><td>WAF-SVC-VNET-07</td><td>Private endpoints are used for Azure services</td><td>Security</td><td>✅ <code>privateEndpoints</code></td></tr><tr><td>WAF-SVC-VNET-08</td><td>Every virtual network has an enabled flow log</td><td>Operational excellence</td><td>✅ <code>virtualNetworks</code> to enabled <code>flowLogs</code></td></tr><tr><td>WAF-SVC-VNET-09</td><td>Flow logs use Traffic Analytics</td><td>Operational excellence</td><td>✅ <code>trafficAnalytics</code></td></tr><tr><td>WAF-SVC-VNET-10</td><td>Azure Virtual Network Manager manages connectivity centrally</td><td>Operational excellence</td><td>✅ <code>networkManagers</code></td></tr><tr><td>WAF-SVC-VNET-11</td><td>Segments are guarded by NSGs and application security groups, with Virtual Network Verifier used before production</td><td>Security</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-VNET-12</td><td>Unused public IP addresses are removed</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-VNET-13</td><td>Connection Monitor measures latency and loss between key endpoints</td><td>Performance efficiency</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-virtual-machines-waf-svc-vm-—-13-items" tabindex="-1">Azure Virtual Machines (WAF-SVC-VM) — 13 items <a class="header-anchor" href="#azure-virtual-machines-waf-svc-vm-—-13-items" aria-label="Permalink to &quot;Azure Virtual Machines (WAF-SVC-VM) — 13 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/virtual-machines" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/virtual-machines</a>. 9 automated, 4 manual.</p><p>The guide covers Virtual Machines and Virtual Machine Scale Sets; scale-set items carry the WAF-SVC-VMSS prefix.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-VM-01</td><td>Virtual machines in zone regions are deployed in an availability zone</td><td>Reliability</td><td>✅ <code>zoneEligible</code>, <code>zoneRedundant</code></td></tr><tr><td>WAF-SVC-VM-02</td><td>Virtual machines have a backup protected item</td><td>Reliability</td><td>✅ <code>virtualMachines</code> to <code>backupProtectedItems</code></td></tr><tr><td>WAF-SVC-VM-03</td><td>Virtual machines use Trusted Launch or Confidential VMs</td><td>Security</td><td>✅ <code>securityType</code></td></tr><tr><td>WAF-SVC-VM-04</td><td>Virtual machines use encryption at host</td><td>Security</td><td>✅ <code>encryptionAtHost</code></td></tr><tr><td>WAF-SVC-VM-05</td><td>Virtual machines have a managed identity</td><td>Security</td><td>✅ <code>identityType</code></td></tr><tr><td>WAF-SVC-VM-06</td><td>Microsoft Defender for Servers is enabled</td><td>Security</td><td>✅ Defender plan <code>VirtualMachines</code></td></tr><tr><td>WAF-SVC-VM-07</td><td>Operating system updates are applied automatically</td><td>Operational excellence</td><td>✅ <code>patchMode</code></td></tr><tr><td>WAF-SVC-VM-08</td><td>Boot diagnostics are enabled</td><td>Operational excellence</td><td>✅ <code>bootDiagnostics</code></td></tr><tr><td>WAF-SVC-VM-09</td><td>Windows Server machines claim Azure Hybrid Benefit</td><td>Cost optimization</td><td>✅ <code>osType</code>, <code>licenseType</code></td></tr><tr><td>WAF-SVC-VM-10</td><td>No machine has a public IP address bound directly, and every network interface has an NSG</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-VM-11</td><td>Always-on machines are locked, health endpoints are emitted, and capacity reservations cover critical workloads</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-VM-12</td><td>The Azure Monitor agent, VM insights and data collection rules cover the machines</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-VM-13</td><td>Sizes, accelerated networking and proximity placement fit the workload</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr></tbody></table><h3 id="azure-virtual-machine-scale-sets-waf-svc-vmss-—-7-items" tabindex="-1">Azure Virtual Machine Scale Sets (WAF-SVC-VMSS) — 7 items <a class="header-anchor" href="#azure-virtual-machine-scale-sets-waf-svc-vmss-—-7-items" aria-label="Permalink to &quot;Azure Virtual Machine Scale Sets (WAF-SVC-VMSS) — 7 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/virtual-machines" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/virtual-machines</a>. 6 automated, 1 manual.</p><p>Scale sets in AKS node resource groups (MC_*) are skipped; the AKS guide governs them.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-VMSS-01</td><td>Scale sets use Flexible orchestration</td><td>Reliability</td><td>✅ <code>orchestrationMode</code></td></tr><tr><td>WAF-SVC-VMSS-02</td><td>Scale sets repair unhealthy instances automatically</td><td>Reliability</td><td>✅ <code>automaticRepairs</code></td></tr><tr><td>WAF-SVC-VMSS-03</td><td>Scale sets span at least two availability zones</td><td>Reliability</td><td>✅ <code>zoneCount</code>, in zone regions</td></tr><tr><td>WAF-SVC-VMSS-04</td><td>Scale sets use encryption at host</td><td>Security</td><td>✅ <code>encryptionAtHost</code></td></tr><tr><td>WAF-SVC-VMSS-05</td><td>Uniform scale sets do not use a manual upgrade policy</td><td>Operational excellence</td><td>✅ <code>upgradeMode</code></td></tr><tr><td>WAF-SVC-VMSS-06</td><td>Scale sets have an enabled autoscale setting</td><td>Performance efficiency</td><td>✅ <code>virtualMachineScaleSets</code> to enabled <code>autoscaleSettings</code></td></tr><tr><td>WAF-SVC-VMSS-07</td><td>Standby pools, overprovisioning, MaxSurge and zone balancing are used where they fit</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-disk-storage-waf-svc-disk-—-9-items" tabindex="-1">Azure Disk Storage (WAF-SVC-DISK) — 9 items <a class="header-anchor" href="#azure-disk-storage-waf-svc-disk-—-9-items" aria-label="Permalink to &quot;Azure Disk Storage (WAF-SVC-DISK) — 9 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-disk-storage" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-disk-storage</a>. 5 automated, 4 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-DISK-01</td><td>Attached LRS disks in zone regions are zonal</td><td>Reliability</td><td>✅ <code>zoneCount</code>, <code>sku</code></td></tr><tr><td>WAF-SVC-DISK-02</td><td>Attached disks are not Standard HDD</td><td>Reliability</td><td>✅ <code>sku</code></td></tr><tr><td>WAF-SVC-DISK-03</td><td>Virtual machines use managed disks</td><td>Reliability</td><td>✅ <code>unmanagedOsDisk</code></td></tr><tr><td>WAF-SVC-DISK-04</td><td>Disks block public network access</td><td>Security</td><td>✅ <code>publicNetworkAccess</code></td></tr><tr><td>WAF-SVC-DISK-05</td><td>Disks use a customer-managed key where policy requires it</td><td>Security</td><td>✅ <code>encryptionType</code></td></tr><tr><td>WAF-SVC-DISK-06</td><td>Resource locks protect disks, and RBAC and short-lived SAS limit access</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-DISK-07</td><td>Disks are protected by Azure Backup, Site Recovery or restore points</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-DISK-08</td><td>Disk type and size match performance needs, and throttling is monitored</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-DISK-09</td><td>Disk types are chosen on cost, and reserved capacity covers Premium SSD</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-monitor-application-insights-waf-svc-appi-—-7-items" tabindex="-1">Azure Monitor Application Insights (WAF-SVC-APPI) — 7 items <a class="header-anchor" href="#azure-monitor-application-insights-waf-svc-appi-—-7-items" aria-label="Permalink to &quot;Azure Monitor Application Insights (WAF-SVC-APPI) — 7 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/application-insights" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/application-insights</a>. 4 automated, 3 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-APPI-01</td><td>Components are workspace-based</td><td>Reliability</td><td>✅ <code>workspaceBased</code></td></tr><tr><td>WAF-SVC-APPI-02</td><td>Components require Microsoft Entra authentication for ingestion</td><td>Security</td><td>✅ <code>disableLocalAuth</code></td></tr><tr><td>WAF-SVC-APPI-03</td><td>Components block public ingestion and query</td><td>Security</td><td>✅ <code>publicNetworkAccessForIngestion</code>, <code>publicNetworkAccessForQuery</code></td></tr><tr><td>WAF-SVC-APPI-04</td><td>One component per workload per environment, in the same region as its workspace</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-APPI-05</td><td>Microsoft Entra authentication is used for the query API, and personal data is not collected</td><td>Security</td><td>✅ <code>disableLocalAuth</code>, <code>disableIpMasking</code>; which scripts query with Entra identities is not read</td></tr><tr><td>WAF-SVC-APPI-06</td><td>A daily cap, sampling and telemetry filters control volume</td><td>Cost optimization</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-APPI-07</td><td>Auto-instrumentation or the Azure Monitor OpenTelemetry distro is used with connection strings</td><td>Operational excellence</td><td>❌ Manual — no collected field</td></tr></tbody></table><h3 id="azure-front-door-waf-svc-afd-—-7-items" tabindex="-1">Azure Front Door (WAF-SVC-AFD) — 7 items <a class="header-anchor" href="#azure-front-door-waf-svc-afd-—-7-items" aria-label="Permalink to &quot;Azure Front Door (WAF-SVC-AFD) — 7 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-front-door" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-front-door</a>. 5 automated, 2 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-AFD-01</td><td>Front Door profiles use the Premium tier</td><td>Security</td><td>✅ <code>sku</code></td></tr><tr><td>WAF-SVC-AFD-02</td><td>A Front Door WAF policy runs in Prevention mode</td><td>Security</td><td>✅ <code>wafPolicies.mode</code></td></tr><tr><td>WAF-SVC-AFD-03</td><td>Profiles send logs and metrics to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.cdn/profiles</code></td></tr><tr><td>WAF-SVC-AFD-04</td><td>Origin groups have redundant origins with health probes, and request timeouts and session affinity are deliberate</td><td>Reliability</td><td>✅ <code>domains.afd.originGroups</code> — a group with fewer than two enabled origins, or two or more and no health probe, fails; timeouts and session affinity are shown on each row, not scored</td></tr><tr><td>WAF-SVC-AFD-05</td><td>Origins are reached over Private Link, TLS 1.2 is the minimum, and managed certificates are used</td><td>Security</td><td>✅ <code>domains.afd.customDomains</code> — a custom domain whose minimum TLS version is below 1.2 fails; Private Link use (<code>origins</code>), the certificate type and HTTP-to-HTTPS redirect (<code>routes</code>) are read and shown but are choices, not scored</td></tr><tr><td>WAF-SVC-AFD-06</td><td>Caching and compression are enabled for cacheable content</td><td>Performance efficiency</td><td>❌ Manual — with evidence: each route&#39;s cache configuration and compression (<code>domains.afd.routes</code>); whether content is cacheable is a judgement about the application</td></tr><tr><td>WAF-SVC-AFD-07</td><td>Alerts and built-in analytics reports are reviewed</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-traffic-manager-waf-svc-tm-—-6-items" tabindex="-1">Azure Traffic Manager (WAF-SVC-TM) — 6 items <a class="header-anchor" href="#azure-traffic-manager-waf-svc-tm-—-6-items" aria-label="Permalink to &quot;Azure Traffic Manager (WAF-SVC-TM) — 6 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-traffic-manager" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-traffic-manager</a>. 4 automated, 2 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-TM-01</td><td>Profiles have more than one endpoint</td><td>Reliability</td><td>✅ <code>endpointCount</code></td></tr><tr><td>WAF-SVC-TM-02</td><td>Profile health probes report the profile online</td><td>Reliability</td><td>✅ <code>monitorStatus</code></td></tr><tr><td>WAF-SVC-TM-03</td><td>Profiles send diagnostic logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of <code>microsoft.network/trafficmanagerprofiles</code></td></tr><tr><td>WAF-SVC-TM-04</td><td>DNS TTL is below 60 seconds, AlwaysServe is off, and probe interval and tolerated failures are set deliberately</td><td>Reliability</td><td>✅ <code>dnsTtl</code>, <code>alwaysServeEndpointCount</code>; probe interval and tolerated failures are not scored</td></tr><tr><td>WAF-SVC-TM-05</td><td>Application gateways front HTTP endpoints, and apex domains use alias records</td><td>Reliability</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-TM-06</td><td>Routing method fits the deployment, using performance routing for multi-region endpoints</td><td>Performance efficiency</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-virtual-wan-waf-svc-vwan-—-9-items" tabindex="-1">Azure Virtual WAN (WAF-SVC-VWAN) — 9 items <a class="header-anchor" href="#azure-virtual-wan-waf-svc-vwan-—-9-items" aria-label="Permalink to &quot;Azure Virtual WAN (WAF-SVC-VWAN) — 9 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-virtual-wan" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-virtual-wan</a>. 4 automated, 5 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-VWAN-01</td><td>Virtual WANs use the Standard SKU</td><td>Reliability</td><td>✅ <code>wanType</code></td></tr><tr><td>WAF-SVC-VWAN-02</td><td>A secured virtual hub runs Azure Firewall</td><td>Security</td><td>✅ <code>azureFirewalls</code> with sku AZFW_Hub</td></tr><tr><td>WAF-SVC-VWAN-03</td><td>Hub gateways send diagnostic logs to a destination</td><td>Operational excellence</td><td>✅ diagnostic-settings coverage of hub gateway types</td></tr><tr><td>WAF-SVC-VWAN-04</td><td>Virtual hubs exist in at least two regions, with zone-redundant, active-active gateways</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-VWAN-05</td><td>Site-to-site VPN backs up ExpressRoute, and routing preference is set deliberately</td><td>Reliability</td><td>✅ <code>expressRouteBackedUp</code>, on hubs that carry an ExpressRoute gateway</td></tr><tr><td>WAF-SVC-VWAN-06</td><td>Spokes use custom route tables, NSGs and private endpoints, and point-to-site uses Microsoft Entra ID with Conditional Access</td><td>Security</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-VWAN-07</td><td>Site-to-site connections use GCMAES256 IPsec policies</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-VWAN-08</td><td>Routing infrastructure units and gateway scale units are sized from throughput</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-VWAN-09</td><td>Alerts, Insights, Connection Monitor and maintenance windows are configured</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-expressroute-waf-svc-er-—-9-items" tabindex="-1">Azure ExpressRoute (WAF-SVC-ER) — 9 items <a class="header-anchor" href="#azure-expressroute-waf-svc-er-—-9-items" aria-label="Permalink to &quot;Azure ExpressRoute (WAF-SVC-ER) — 9 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-expressroute" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-expressroute</a>. 4 automated, 5 manual.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-ER-01</td><td>More than one ExpressRoute circuit exists</td><td>Reliability</td><td>✅ <code>expressRouteCircuits</code></td></tr><tr><td>WAF-SVC-ER-02</td><td>ExpressRoute gateways are zone redundant</td><td>Reliability</td><td>✅ <code>vpnGateways</code> sku</td></tr><tr><td>WAF-SVC-ER-03</td><td>A site-to-site VPN gateway can back up ExpressRoute</td><td>Reliability</td><td>✅ <code>vpnGateways</code> of type Vpn</td></tr><tr><td>WAF-SVC-ER-04</td><td>No circuit is left unprovisioned</td><td>Cost optimization</td><td>✅ <code>serviceProviderProvisioningState</code></td></tr><tr><td>WAF-SVC-ER-05</td><td>Both connections of each circuit run active-active, with site resiliency across peering locations</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ER-06</td><td>The circuit SKU fits geographic reach, and Global Reach joins on-premises sites</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ER-07</td><td>MACsec, IPsec and MD5 protect traffic where required</td><td>Security</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-ER-08</td><td>Circuit, port and gateway metrics have alerts, and Service Health and Connection Monitor are configured</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ER-09</td><td>Circuit bandwidth, gateway SKU, FastPath and scalable gateways match throughput needs</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr></tbody></table><h3 id="azure-files-waf-svc-files-—-9-items" tabindex="-1">Azure Files (WAF-SVC-FILES) — 9 items <a class="header-anchor" href="#azure-files-waf-svc-files-—-9-items" aria-label="Permalink to &quot;Azure Files (WAF-SVC-FILES) — 9 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-files" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-files</a>. 6 automated, 3 manual.</p><p>Scout cannot see which storage accounts hold file shares, so the account-level items apply to every account that can (StorageV2, FileStorage, Storage).</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-FILES-01</td><td>Storage accounts use zone- or geo-redundant storage</td><td>Reliability</td><td>✅ <code>sku</code></td></tr><tr><td>WAF-SVC-FILES-02</td><td>Storage accounts require TLS 1.2 or higher</td><td>Security</td><td>✅ <code>minTls</code></td></tr><tr><td>WAF-SVC-FILES-03</td><td>Secure transfer is required</td><td>Security</td><td>✅ <code>httpsOnly</code></td></tr><tr><td>WAF-SVC-FILES-04</td><td>Public network access is disabled or limited by a deny-by-default firewall</td><td>Security</td><td>✅ <code>publicNetworkAccess</code>, <code>networkDefaultDeny</code></td></tr><tr><td>WAF-SVC-FILES-05</td><td>Soft delete, snapshots and Azure Backup protect shares</td><td>Reliability</td><td>✅ <code>fileServiceProperties</code> <code>shareDeleteRetentionEnabled</code>; snapshots and backup are not read</td></tr><tr><td>WAF-SVC-FILES-06</td><td>Identity-based authentication uses Kerberos with AES-256, SMB 3.1.1 with AES-256-GCM, and keys are in Key Vault</td><td>Security</td><td>✅ <code>fileServiceProperties</code> <code>smbVersions</code> and <code>smbChannelEncryption</code> (null allows every version and algorithm, which is a finding); Kerberos ticket encryption and key custody are not read</td></tr><tr><td>WAF-SVC-FILES-07</td><td>A Resource Manager lock protects the storage account</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-FILES-08</td><td>SMB Multichannel, metadata caching and nconnect are used for SSD shares, and throttling is monitored</td><td>Performance efficiency</td><td>❌ Manual — no collected field</td></tr><tr><td>WAF-SVC-FILES-09</td><td>Access tiers, provisioned capacity and reservations match usage</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h3 id="azure-netapp-files-waf-svc-anf-—-8-items" tabindex="-1">Azure NetApp Files (WAF-SVC-ANF) — 8 items <a class="header-anchor" href="#azure-netapp-files-waf-svc-anf-—-8-items" aria-label="Permalink to &quot;Azure NetApp Files (WAF-SVC-ANF) — 8 items&quot;">​</a></h3><p>Guide: <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-netapp-files" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/well-architected/service-guides/azure-netapp-files</a>. 0 automated, 8 manual.</p><p>The assessment collects volume name, state and quota only, so every item here is a question; volumes are attached as evidence.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Pillar</th><th>Scout</th></tr></thead><tbody><tr><td>WAF-SVC-ANF-01</td><td>Snapshots, backup and cross-region or cross-zone replication protect volumes</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ANF-02</td><td>The delegated subnet is sized for growth and uses standard network features</td><td>Reliability</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ANF-03</td><td>Network access is limited by NSGs, export policies and protocol-level access controls</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ANF-04</td><td>Data is encrypted in transit and at rest, with customer-managed or double encryption where required</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ANF-05</td><td>File access logs feed monitoring, and RBAC and Azure Policy restrict insecure volumes</td><td>Security</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ANF-06</td><td>Service level, volume size and QoS match performance needs</td><td>Performance efficiency</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ANF-07</td><td>Cool access, reservations, and consolidated capacity pools lower the cost</td><td>Cost optimization</td><td>❌ Manual — evidence attached</td></tr><tr><td>WAF-SVC-ANF-08</td><td>Volume performance and health are monitored, and deployments are automated</td><td>Operational excellence</td><td>❌ Manual — evidence attached</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service guide</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Azure Kubernetes Service</td><td>14</td><td>12</td><td>2</td></tr><tr><td>Azure App Service (Web Apps)</td><td>17</td><td>14</td><td>3</td></tr><tr><td>Azure Functions</td><td>7</td><td>4</td><td>3</td></tr><tr><td>Azure Container Apps</td><td>11</td><td>8</td><td>3</td></tr><tr><td>Azure API Management</td><td>12</td><td>9</td><td>3</td></tr><tr><td>Azure Service Bus</td><td>13</td><td>9</td><td>4</td></tr><tr><td>Azure Event Grid</td><td>10</td><td>6</td><td>4</td></tr><tr><td>Azure Firewall</td><td>11</td><td>7</td><td>4</td></tr><tr><td>Azure Application Gateway</td><td>13</td><td>9</td><td>4</td></tr><tr><td>Azure Load Balancer</td><td>9</td><td>5</td><td>4</td></tr><tr><td>Azure Virtual Network</td><td>13</td><td>10</td><td>3</td></tr><tr><td>Azure Virtual Machines</td><td>13</td><td>9</td><td>4</td></tr><tr><td>Azure Virtual Machine Scale Sets</td><td>7</td><td>6</td><td>1</td></tr><tr><td>Azure Disk Storage</td><td>9</td><td>5</td><td>4</td></tr><tr><td>Azure Monitor Application Insights</td><td>7</td><td>4</td><td>3</td></tr><tr><td>Azure Front Door</td><td>7</td><td>3</td><td>4</td></tr><tr><td>Azure Traffic Manager</td><td>6</td><td>4</td><td>2</td></tr><tr><td>Azure Virtual WAN</td><td>9</td><td>4</td><td>5</td></tr><tr><td>Azure ExpressRoute</td><td>9</td><td>4</td><td>5</td></tr><tr><td>Azure Files</td><td>9</td><td>6</td><td>3</td></tr><tr><td>Azure NetApp Files</td><td>8</td><td>0</td><td>8</td></tr><tr><td><strong>Total</strong></td><td><strong>214</strong></td><td><strong>142</strong></td><td><strong>72</strong></td></tr></tbody></table><h2 id="what-these-rules-read" tabindex="-1">What these rules read <a class="header-anchor" href="#what-these-rules-read" aria-label="Permalink to &quot;What these rules read&quot;">​</a></h2><p>The rules read the fields the assessment collection gained in AB#9300 phase 4, such as AKS <code>disableLocalAccounts</code>, <code>upgradeChannel</code> and <code>authorizedIpRangeCount</code>; web app and Container Apps exposure fields; API Management <code>zoneCount</code> and <code>capacity</code>; Service Bus, Event Grid and storage TLS and local-authentication settings; Firewall, Application Gateway and Load Balancer zone, tier and probe fields; virtual network <code>encryptionEnabled</code>, <code>publicIPAddresses</code> and <code>flowLogs</code>; and virtual machine, scale set and disk security fields. Only a boolean or a count is collected for anything sensitive: no key, certificate, secret value, IP address list or workspace id is read.</p><p>Four items read the per-resource ARM settings added in AB#9300 phase 4, batch 2, each from a dataset with a sibling <code>&lt;name&gt;Measured</code> flag: App Service configuration (<code>webAppConfig</code>) and basic-authentication policies (<code>webAppBasicAuth</code>) for WAF-SVC-APP-13 and APP-14, and the Azure Files service properties (<code>fileServiceProperties</code>) for WAF-SVC-FILES-05 and FILES-06. The rule is gated on that flag, so a run that never read the setting reports the item Not assessed rather than passed. A site, account or policy whose read failed has no row and is not scored. Only a boolean, a count or a protocol string is collected: no app setting, connection string or credential is read.</p><p>Virtual network flow logs are matched to virtual networks by lower-cased resource id. A flow log whose target is a subnet or a network interface is not matched, and NSG flow logs (which Microsoft is retiring) are not counted as virtual network flow logs.</p>',88)])])}const m=e(i,[["render",o]]);export{p as __pageData,m as default};
